import type { Meta, StoryObj } from "@storybook/vue3";
import { h, ref } from "vue";
import { Star01 } from "@kozmos-ds/icons/vue";
import { KozmosInput } from "../../index";

/**
 * Vue's Input: the stories React's has, with the same names, each drawn as
 * React's story draws it, inside the KozmosThemeProvider the Storybook's
 * decorator gives every story. test/parity/input.parity.spec.ts draws each
 * in both and holds Vue's render to React's. Generated by `port Input`; the
 * stories React draws by hand written by hand, as render functions, so each
 * of React's text nodes is one here too.
 */
type Args = Record<string, unknown>;

const meta: Meta<Args> = {
  title: "Vue/Core/Inputs/Input",
  component: KozmosInput,
  parameters: { layout: "centered" },
  argTypes: {
    type: {
      control: "select",
      options: ["text", "password", "email", "number", "tel", "url"],
    },
    status: {
      control: "select",
      options: ["default", "error", "warning", "success"],
    },
  },
};

export default meta;
type Story = StoryObj<Args>;

const STORY_BOX = "grid w-full max-w-sm items-center gap-1.5 align-middle";

/** One field in the stories' box, React's props first and the story's args over them. */
const boxed = (props: Args) => (args: Args) => ({
  setup: () => () =>
    h("div", { class: STORY_BOX }, [h(KozmosInput, { ...props, ...args })]),
});

export const Default: Story = {
  render: boxed({
    type: "email",
    id: "email",
    label: "Email",
    placeholder: "Email",
  }),
};

export const WithHelperText: Story = {
  render: boxed({
    type: "email",
    id: "email-helper",
    label: "Email",
    placeholder: "Email",
    helperText: "Use your work email address.",
  }),
};

export const WithError: Story = {
  render: boxed({
    type: "email",
    id: "email-error",
    label: "Email",
    placeholder: "Email",
    error: "Invalid email address.",
  }),
};

export const ValidationStates: Story = {
  render: () => ({
    setup: () => () =>
      h(
        "div",
        { class: "grid w-full max-w-sm items-center gap-4 align-middle" },
        [
          h(KozmosInput, {
            label: "Default",
            placeholder: "Placeholder",
            helperText: "Helper text",
          }),
          h(KozmosInput, {
            label: "Warning",
            placeholder: "Placeholder",
            status: "warning",
            helperText: "Check this value.",
          }),
          h(KozmosInput, {
            label: "Success",
            placeholder: "Placeholder",
            status: "success",
            helperText: "Looks good.",
          }),
          h(KozmosInput, {
            label: "Readonly",
            placeholder: "Placeholder",
            readonly: true,
            helperText: "This value cannot be edited.",
          }),
        ],
      ),
  }),
};

/**
 * GAP-154: Pointr Cloud's POI editor, a feature's ID read-only with a copy
 * action that says it copied, and the Featured star as a toggle at a
 * field's end. The toggle's icon is an `@kozmos-ds/icons/vue` glyph.
 */
export const Actions: Story = {
  render: () => ({
    setup: () => {
      const featured = ref(true);
      return () =>
        h("div", { class: "grid w-full max-w-sm gap-4" }, [
          h(KozmosInput, {
            label: "FID",
            readonly: true,
            defaultValue: "5f0c2a7e-91d4-4b1e-a0f3-6c8e2d1b9a47",
            action: { kind: "copy", label: "Copy FID" },
          }),
          h(KozmosInput, {
            label: "Name",
            defaultValue: "Gate B12",
            action: {
              kind: "toggle",
              label: "Featured",
              icon: h(Star01, { "aria-hidden": "true" }),
              pressed: featured.value,
              onPressedChange: (next: boolean) => (featured.value = next),
            },
          }),
        ]);
    },
  }),
};

/**
 * GAP-212, decision 224: Pointr Cloud's Map Personas, a persona's ID and
 * its Map Style read-only, each with a pencil at the field's end that opens
 * its editor. What editing means is the product's: here it makes the field
 * editable.
 */
export const EditAction: Story = {
  render: () => ({
    setup: () => {
      const editing = ref(false);
      return () =>
        h("div", { class: "grid w-full max-w-sm gap-4" }, [
          h(KozmosInput, {
            label: "ID",
            readonly: true,
            defaultValue: "staff",
            action: { kind: "edit", label: "Edit ID", onEdit: () => {} },
          }),
          h(KozmosInput, {
            label: "Map Style",
            readonly: !editing.value,
            defaultValue: "https://styles.example.com/persona/staff.json",
            action: {
              kind: "edit",
              label: "Edit Map Style",
              onEdit: () => (editing.value = true),
            },
          }),
        ]);
    },
  }),
};

/**
 * GAP-153: a property of a multi-selection whose features differ. The
 * field shows "Multiple values" and is described with it until it is
 * edited; then it offers "Reset to multiple values", which takes it back.
 * Type in the first field to see the reset; the second has been edited
 * already.
 */
export const MixedValue: Story = {
  render: () => ({
    setup: () => {
      const field = (label: string, edited?: string) => {
        const edit = ref<string | undefined>(edited);
        return () =>
          h(KozmosInput, {
            label,
            mixed: edit.value === undefined,
            modelValue: edit.value ?? "",
            "onUpdate:modelValue": (next: string) => (edit.value = next),
            onResetMixed: () => (edit.value = undefined),
          });
      };
      const name = field("Name");
      const description = field("Description", "Gate seating");
      return () =>
        h("div", { class: "grid w-80 gap-4" }, [name(), description()]);
    },
  }),
};
